/* Connected examples and explanatory practice, stored with the learning notebook. */
(()=>{
 'use strict';
 const C=window.REILearningLab,S=window.REILearningStore;if(!C||!S)return;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const option=(v,label,selected)=>`<option value="${v}" ${v===selected?'selected':''}>${label}</option>`;
 let saved=S.available();
 function persist(next){saved=S.write(next);document.querySelectorAll('[data-lab-save]').forEach(el=>el.textContent=saved?'Saved on this device · included in your learning notebook backup.':'Not saved to this device. Keep this page open and export a learning notebook backup from My workspace.');return saved}
 function toolbar(stage){const r=S.read();return `<div class="lab-settings"><label>Example project<select data-lab-case>${option('qualitative',C.cases.qualitative.label,r.case)}${option('quantitative',C.cases.quantitative.label,r.case)}</select></label><label>Writing support<select data-lab-support>${option('auto','Gradually reduce guidance',r.support)}${option('guided','Guided · show the structure',r.support)}${option('hints','Hints · prompt my thinking',r.support)}${option('independent','Independent · let me try',r.support)}</select></label></div><p class="lab-note" data-lab-save role="status">${saved?'Your choices and practice stay on this device and travel in learning notebook backups.':'Not saved to this device. Keep this page open and export a learning notebook backup from My workspace.'}</p>${Number.isInteger(stage)?`<p class="lab-note">Guidance now: <strong>${C.support(stage,r.support)}</strong>. Choose the support you need; this is not tied to your college year.</p>`:''}`}
 function caseBody(stage){const c=C.cases[S.read().case],x=c.stages[stage];return `<div class="lab-case-heading"><h3>${esc(c.title)}</h3><p>Stage ${stage+1} of 9 · ${esc(C.titles[stage])}</p></div><p class="lab-fiction">Fictional teaching project. All source records, samples and reported findings below are invented. Do not cite them or use them as evidence in your own project.</p><div class="lab-manuscript"><h4>Worked output</h4><p>${esc(x.draft)}</p></div><div class="lab-reason"><h4>Why this decision?</h4><p>${esc(x.reason)}</p><h4>What remains uncertain?</h4><p>${esc(x.limit)}</p></div><details class="lab-sources"><summary>Inspect the teaching evidence trail</summary><p>The same three invented records accompany this project through all nine stages.</p>${c.sources.map(s=>`<article><h4>${s.id} · ${esc(s.title)}</h4><dl><dt>Design</dt><dd>${esc(s.method)}</dd><dt>Teaching finding</dt><dd>${esc(s.finding)}</dd><dt>Boundary</dt><dd>${esc(s.limit)}</dd></dl></article>`).join('')}</details>${stage===8?`<details class="lab-connected-draft"><summary>Read the connected proposal draft</summary><p class="lab-fiction">Assembled from the earlier teaching stages. This provisional draft uses invented source records and has no approval or results.</p>${[0,1,3,4,5,6,7].map(i=>`<section><h4>${esc(C.titles[i])}</h4><p>${esc(c.stages[i].draft)}</p></section>`).join('')}<h4>Access, schedule and review</h4><p>Confirm access and institutional requirements first. Allow time for literature review and instrument preparation, followed by recruitment and collection only after required review. Reserve time for analysis, supervisor feedback and revisions. If access or response is inadequate, revisit scope before promising an outcome.</p><h4>Limits and status</h4><p>${esc(c.stages[7].limit)} ${esc(x.limit)}</p></details>`:''}<nav class="lab-stage-nav" aria-label="Follow this example project">${C.titles.map((t,i)=>`<a href="#lesson/${i}/example" ${i===stage?'aria-current="step"':''}><span>${i+1}</span>${esc(t)}</a>`).join('')}</nav>`}
 function worked(stage){return `<section class="learning-lab lab-worked" data-lab-stage="${stage}"><h2>Follow one study from curiosity to proposal.</h2><p>Switch projects to compare how an experience question and an association question change the research decisions.</p>${toolbar(stage)}<div data-lab-case-body>${caseBody(stage)}</div></section>`}
 function help(stage){const mode=C.support(stage,S.read().support),p=C.prompts[stage],c=C.cases[S.read().case].stages[stage];return `<div class="lab-writing-help" data-lab-help><h3>${mode==='guided'?'Build the reasoning, one decision at a time.':mode==='hints'?'A few prompts before you write.':'Try your reasoning independently.'}</h3>${mode==='guided'?`<p>${esc(p[1])}</p><details><summary>See how the teaching project handles this stage</summary><p>${esc(c.draft)}</p><p><strong>Reason:</strong> ${esc(c.reason)}</p><p class="lab-fiction">Fictional example. Write your own account using real sources.</p></details>`:mode==='hints'?`<p>${esc(p[1])}</p><details><summary>Bring back a worked explanation</summary><p>${esc(c.reason)}</p><a href="#lesson/${stage}/example">Study the complete example</a></details>`:`<p>Write before looking at the model. Explain the choices and boundaries in your own project.</p><details><summary>Show a hint when I need one</summary><p>${esc(p[1])}</p><a href="#lesson/${stage}/example">Bring back the worked example</a></details>`}</div>`}
 function practiceItem(stage,n,a){const q=C.practice[stage][n],f=C.feedback(stage,n,a.submitted[n]);return `<form class="lab-practice-item" data-lab-practice="${n}"><fieldset><legend>${n+1}. ${esc(q.ask)}</legend>${q.options.map((o,i)=>`<label><input type="radio" name="lab-answer" value="${i}" ${a.choices[n]===i?'checked':''} required><span>${esc(o)}</span></label>`).join('')}</fieldset><button class="button secondary" type="submit">Explain my choice</button><p class="lab-feedback" data-lab-feedback="${n}" role="status">${f?`<strong>${f.correct?'This choice fits.':'Reconsider this choice.'}</strong> ${esc(f.text)}`:''}</p></form>`}
 function practice(stage){const a=C.attempt(S.read(),stage),p=C.prompts[stage];return `<section class="learning-lab lab-practice" data-lab-stage="${stage}"><h2>Make a decision. Explain the reason.</h2><p>Try these situations before reading the feedback. Revise your choices as your understanding changes.</p><p class="lab-note" data-lab-save role="status">${saved?'Your practice stays on this device and travels in learning notebook backups.':'Not saved to this device. Keep this page open and export a learning notebook backup from My workspace.'}</p><button type="button" class="text-button" data-lab-retry>Try choices again without feedback</button>${C.practice[stage].map((q,n)=>practiceItem(stage,n,a)).join('')}<div class="lab-reflection"><h3>Put the reasoning in your own words.</h3><label for="lab-reflection-${stage}">${esc(p[0])}</label><textarea id="lab-reflection-${stage}" data-lab-reflection rows="6" maxlength="100000" placeholder="Explain the decision, its evidence and what it cannot establish…">${esc(a.reflection)}</textarea><p class="lab-note">This practice is separate from your project draft. REI saves your response; it does not automatically grade written reasoning.</p><button type="button" class="button secondary" data-lab-compare ${!a.reflection.trim()?'disabled':''}>Compare my reasoning</button><div data-lab-model ${a.compared?'':'hidden'}><h4>Self-review prompts</h4><p>${esc(p[1])}</p><h4>One defensible line of reasoning</h4><p>${esc(p[2])}</p><p>Other answers can be defensible. Check your evidence and assumptions, then revise your explanation rather than copying the model.</p></div></div><p class="lab-note">Completion records an activity. Correct choices and self-review do not certify research quality or mastery. Revisit this practice later without the explanation visible.</p></section>`}
 function methods(){return `<div class="lab-methods"><h3>From question to a defensible method.</h3><p>Use these six lenses together. Follow the requirements of your discipline, institution and supervisor.</p>${C.methods.map(m=>`<details><summary>${m.title}</summary><p>${esc(m.body)}</p><h4>In practice</h4><p>${esc(m.example)}</p><h4>Ask yourself</h4><p>${esc(m.check)}</p>${m.source?`<a href="${m.source[1]}" target="_blank" rel="noopener noreferrer">${esc(m.source[0])} ↗</a>`:''}</details>`).join('')}</div>`}
 function explorer(){return `<section class="learning-lab lab-explorer"><h2>Change the question. Watch the method change.</h2><p>A conceptual sandbox: choose an intended claim and collection method, then inspect whether the evidence can answer the question. It does not edit your project.</p><div class="lab-settings"><label>What do I want to understand?<select data-lab-goal>${option('experience','Experiences and meanings','experience')}${option('association','An association between variables','experience')}${option('effect','A causal effect of an intervention','experience')}</select></label><label>How will I collect evidence?<select data-lab-collection>${option('interview','Open-ended interviews','interview')}${option('survey','One-time observational survey','interview')}${option('trial','Randomly assigned intervention trial','interview')}</select></label><label>Who will participate?<select data-lab-sampling>${option('volunteer','Accessible volunteers','volunteer')}${option('structured','A justified selection plan','volunteer')}</select></label></div><div data-lab-diagram>${diagram('experience','interview','volunteer')}</div></section>`}
 function diagram(goal,collection,sampling){const d=C.decide(goal,collection,sampling);return `<div class="lab-chain" aria-label="The question, evidence, analysis and claim form a connected chain"><svg viewBox="0 0 600 70" aria-hidden="true" focusable="false"><path d="M45 35H555"/><path d="m180 28 7 7-7 7m200-14 7 7-7 7"/>${[45,215,385,555].map((x,i)=>`<circle cx="${x}" cy="35" r="19"/><text x="${x}" y="40" text-anchor="middle">${i+1}</text>`).join('')}</svg><ol><li><strong>Question</strong><span>${esc({experience:'Explore an experience',association:'Estimate an association',effect:'Estimate an intervention effect'}[goal])}</span></li><li><strong>Evidence needed</strong><span>${d.need}</span></li><li><strong>Analysis offered</strong><span>${d.analysis}</span></li><li><strong>Claim boundary</strong><span>${d.claim}</span></li></ol></div><div class="lab-diagnosis" role="status"><h3>${d.fit?'A possible fit':'A mismatch to resolve'}</h3><p>${d.explanation}</p><p><strong>Sampling changes the reach:</strong> ${d.reach}</p></div><details><summary>Why selection and assignment are different</summary><p>Random selection concerns who enters a sample. Random assignment concerns which condition participants receive. A population claim and a causal claim require different justifications. No single dropdown choice establishes either.</p></details>`}
 function mount(){saved=S.available();
  const parts=location.hash.slice(1).split('/'),stage=Number(parts[1]);
  if(parts[0]==='academy'){const body=document.querySelector('#main .page-body');if(body&&!body.querySelector('.lab-intro'))body.insertAdjacentHTML('afterbegin',`<section class="learning-lab lab-intro"><h2>Learn the decisions behind the research.</h2><p>Follow two fictional studies through all nine stages. Use worked explanations, fading writing support, scenario practice and a method sandbox. Choose guidance by experience, rather than college year.</p><div class="actions"><a class="button secondary" href="#lesson/0/example">Follow the teaching projects</a><a class="text-link" href="#lesson/7">Explore methods in depth</a></div><p class="lab-note">Milestones record activity. REI’s learning impact has not yet been evaluated with students.</p></section>`);return}
  if(parts[0]==='lesson'&&Number.isInteger(stage)&&stage>=0&&stage<9){const main=document.querySelector('.lesson-main');if(!main||main.querySelector('.learning-lab'))return;const step=main.dataset.step;
   if(step==='example'){const content=main.querySelector('.lesson-content');content.innerHTML=worked(stage)}
   if(step==='write'){const exercise=main.querySelector('.exercise');exercise.insertAdjacentHTML('afterbegin',`<section class="learning-lab lab-support" data-lab-stage="${stage}"><h2>Make the project your own.</h2>${toolbar(stage)}${help(stage)}</section>`)}
   if(step==='check'){const exercise=main.querySelector('.exercise');const quiz=exercise.querySelector('.quiz');if(quiz)quiz.querySelector('h3').textContent='Quick concept check';const completion=exercise.querySelector('.completion-bar');completion.insertAdjacentHTML('beforebegin',practice(stage));completion.insertAdjacentHTML('afterend','<p class="lab-completion-note">Milestone status tracks the original draft and quick concept check. Scenario practice is available for deeper review; neither is a mastery assessment.</p>')}
   if(step==='learn'){const content=main.querySelector('.lesson-content');const term=C.glossary[stage];content.insertAdjacentHTML('beforeend',`<section class="learning-lab lab-concept"><h3>A term to carry forward</h3><dl><dt>${esc(term[0])}</dt><dd>${esc(term[1])}</dd></dl><a href="#lesson/${stage}/example">See the decision in both teaching projects</a></section>${stage===5||stage===7?explorer():''}${stage===7?`<section class="learning-lab">${methods()}</section>`:''}`)}
  }
  if(parts[0]==='research'&&parts[2]==='design'){const head=document.querySelector('.research-content>.research-section-label');if(head&&!document.querySelector('.lab-room-guide'))head.insertAdjacentHTML('afterend',`<details class="learning-lab lab-room-guide"><summary>Learn how question, sampling and analysis fit together</summary><p>Use this teaching guide beside your own alignment worksheet. Choices here are illustrative and do not change saved project records.</p>${methods()}${explorer()}<a href="#lesson/7/example">Compare the two complete methodology examples</a></details>`)}
 }
 document.addEventListener('change',e=>{
  if(e.target.matches('[data-lab-case],[data-lab-support]')){const r=S.read();r[e.target.matches('[data-lab-case]')?'case':'support']=e.target.value;persist(r);const panel=e.target.closest('[data-lab-stage]'),stage=Number(panel?.dataset.labStage);if(panel){const body=panel.querySelector('[data-lab-case-body]');if(body)body.innerHTML=caseBody(stage);const hints=panel.querySelector('[data-lab-help]');if(hints)hints.outerHTML=help(stage);const notes=panel.querySelectorAll('.lab-note');const guidance=Array.from(notes).find(n=>n.textContent.startsWith('Guidance now:'));if(guidance)guidance.innerHTML=`Guidance now: <strong>${C.support(stage,r.support)}</strong>. Choose the support you need; this is not tied to your college year.`}}
  if(e.target.matches('[data-lab-goal],[data-lab-collection],[data-lab-sampling]')){const root=e.target.closest('.lab-explorer');root.querySelector('[data-lab-diagram]').innerHTML=diagram(root.querySelector('[data-lab-goal]').value,root.querySelector('[data-lab-collection]').value,root.querySelector('[data-lab-sampling]').value)}
  if(e.target.matches('.lab-practice-item input')){const panel=e.target.closest('[data-lab-stage]'),stage=Number(panel.dataset.labStage),n=Number(e.target.closest('form').dataset.labPractice),r=S.read(),a=C.attempt(r,stage);a.choices[n]=Number(e.target.value);a.submitted[n]=null;r.attempts[stage]=a;persist(r);panel.querySelector(`[data-lab-feedback="${n}"]`).textContent='Choice changed. Ask for feedback again to review your reasoning.'}
 });
 document.addEventListener('input',e=>{if(!e.target.matches('[data-lab-reflection]'))return;const panel=e.target.closest('[data-lab-stage]'),stage=Number(panel.dataset.labStage),r=S.read(),a=C.attempt(r,stage);a.reflection=e.target.value;a.compared=false;r.attempts[stage]=a;persist(r);panel.querySelector('[data-lab-compare]').disabled=!a.reflection.trim();panel.querySelector('[data-lab-model]').hidden=true});
 document.addEventListener('submit',e=>{const form=e.target.closest('[data-lab-practice]');if(!form)return;e.preventDefault();const panel=form.closest('[data-lab-stage]'),stage=Number(panel.dataset.labStage),n=Number(form.dataset.labPractice),selected=form.querySelector('input:checked');if(!selected)return;const r=S.read(),a=C.attempt(r,stage);a.choices[n]=Number(selected.value);a.submitted[n]=a.choices[n];r.attempts[stage]=a;persist(r);const f=C.feedback(stage,n,a.submitted[n]);form.querySelector('[data-lab-feedback]').innerHTML=`<strong>${f.correct?'This choice fits.':'Reconsider this choice.'}</strong> ${esc(f.text)}`});
 document.addEventListener('click',e=>{const retry=e.target.closest('[data-lab-retry]');if(retry){const panel=retry.closest('[data-lab-stage]'),stage=Number(panel.dataset.labStage),r=S.read(),a=C.attempt(r,stage);a.choices=[null,null,null];a.submitted=[null,null,null];r.attempts[stage]=a;persist(r);panel.querySelectorAll('.lab-practice-item').forEach((form,n)=>form.outerHTML=practiceItem(stage,n,a));panel.querySelector('.lab-practice-item input').focus();return}const b=e.target.closest('[data-lab-compare]');if(!b)return;const panel=b.closest('[data-lab-stage]'),stage=Number(panel.dataset.labStage),r=S.read(),a=C.attempt(r,stage);if(!a.reflection.trim())return;a.compared=true;r.attempts[stage]=a;persist(r);panel.querySelector('[data-lab-model]').hidden=false});
 addEventListener('rrh:route',mount);addEventListener('rei:research-render',mount);mount();
})();
